"""Build VenueAlign's public, readable static pages. Usage: python3 build.py OUTPUT_DIR."""
import sys, html, json
from pathlib import Path
import scenic
from instruments import icon, width_chart, stock_table, contact_chain
from art import mark,brand,illustration
from content import PRODUCTS as P,ROLES as R
out=Path(sys.argv[1]).resolve()
out.mkdir(parents=True,exist_ok=True)
brand(out)
def esc(s): return html.escape(s,quote=True)
def a(slug,label,cls=''): return f'<a class="{cls}" href="{slug}.html">{label}</a>'
def cta(slug,label,style=''): return a(slug,label,'btn '+style)
def ey(s): return '<p class="eyeline"><b aria-hidden="true"></b>'+s+'</p>'
def logo(): return a('index',mark()+'<span>VenueAlign</span>','brand')
def linklist(items): return ''.join(a(s,n) for s,n in items)
def hgroup(label,title,body=''): return f'<header class="hgroup">{ey(label)}<h2>{title}</h2>'+ (f'<p class="lead">{body}</p>' if body else '')+'</header>'
def steps(items): return '<div class="steps">'+''.join(f'<article><span class="rule"></span><h3>{title}</h3><p>{body}</p></article>' for title,body in items)+'</div>'
def faq(items): return '<div class="faqs">'+''.join(f'<details><summary>{q}</summary><p>{ans}</p></details>' for q,ans in items)+'</div>'
def close(title='Bring one unresolved stop.',body='Bring the rider, the venue file and the person who owned the decision. Build a paid comparison around a case you already know.'):
    return f'<section class="closing"><div class="wrap closegrid"><div>{ey("The paid evaluation")}<h2>{title}</h2><p>{body}</p><div class="actions">{cta("pilot","Scope a pilot","accent")}{cta("request-demo","Request a guided demo","outline-light")}</div></div>{scenic.packet()}</div></section>'
productlinks=[(d['slug'],d['name']) for d in P]
rolelinks=[(r[0],r[1]) for r in R]
def header():
    descriptions=['Extract rider requirements','Compare a room with the rider','Sequence the crew handoffs','Issue the reviewed record']
    offers=''.join(f'<a href="{slug}.html">{icon(slug)}<span><b>{name}</b><small>{detail}</small></span></a>' for (slug,name),detail in zip(productlinks,descriptions))
    products='<details class="navgroup"><summary>Products</summary><div class="flyout offersmenu">'+offers+a('products','All products →','alloffers')+'</div></details>'
    links=products+a('solutions','Use cases')+a('pricing','Pricing')+a('company','Company')
    return '<a class="skip" href="#main">Skip to content</a><header class="top"><div class="navinner">'+logo()+'<button class="hamb" aria-expanded="false" aria-controls="mainnav">Menu</button><nav id="mainnav" aria-label="Main navigation">'+links+a('demo','Demo','mobileonly')+a('sign-in','Sign in','mobileonly')+'</nav><div class="navend">'+a('demo',icon('play')+'Demo','demolink')+cta('pilot','Request a pilot','small dark')+'</div></div></header>'
def footer():
    groups=[('Products',[('products','All products')]+productlinks+[('platform','Platform')]),('Explore',[('problem','Why change'),('solutions','Use cases'),('demo','Case workbench'),('buyer-account','Buyer account demo'),('results','Evaluation scorecard'),('validation','Validation plan')]),('Company',[('company','About'),('pricing','Pricing'),('pilot','Paid pilot'),('request-demo','Guided demo'),('contact','Contact'),('sign-in','Sign in')]),('Resources',[('sources','Sources'),('trust','Technical review'),('privacy','Privacy'),('terms','Preview terms')])]
    return '<footer><div class="wrap"><div class="footgrid"><div>'+logo()+'<p>Production advance for touring teams and venues.</p></div>'+''.join('<div><h3>'+n+'</h3>'+linklist(items)+'</div>' for n,items in groups)+'</div><div class="footbase"><span>© 2026 VenueAlign</span><span>Research-stage concept · Fictional preview records</span></div></div></footer>'
registry=[]
def page(slug,title,desc,markup):
    registry.append((slug,title,desc))
    (out/(slug+'.html')).write_text(f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#182e2c"><title>{esc(title)} | VenueAlign</title><meta name="description" content="{esc(desc)}"><meta property="og:title" content="{esc(title)} | VenueAlign"><meta property="og:description" content="{esc(desc)}"><meta property="og:image" content="assets/scenic-hero.webp"><link rel="icon" href="favicon.svg" type="image/svg+xml"><link rel="apple-touch-icon" href="assets/brand/apple.png"><link rel="preload" href="assets/fonts/Newsreader.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="site.css"><script defer src="assets/vendor/gsap.min.js"></script><script defer src="assets/vendor/ScrollTrigger.min.js"></script><link rel="stylesheet" href="instruments.css"><link rel="stylesheet" href="scenic.css"><script defer src="assets/vendor/lenis.min.js"></script><script defer src="site.js"></script></head><body data-page="{slug}">{header()}<main id="main">{markup}</main>{footer()}</body></html>''')
def productcards():
    return '<div class="railbox"><div class="productrail" aria-label="Four products">'+''.join(f'<article class="productcard"><a href="{p["slug"]}.html" class="art art{i}" aria-label="Explore {p["name"]}">{illustration(i)}</a><div class="pcinfo"><p class="mono">{icon(p["slug"])}{["DOCUMENT INTAKE","FIRST PAID MODULE","CREW SEQUENCING","REVIEWED HANDOFF"][i]}</p><h3>{a(p["slug"],p["name"])}</h3><p>{p["short"]}</p>{a(p["slug"],"Explore "+p["name"],"textlink")}</div></article>' for i,p in enumerate(P))+'</div><div class="railcontrols"><span class="mono">FOUR PROPOSED MODULES</span><div><button aria-label="Previous product" data-rail="-1">‹</button><button aria-label="Next product" data-rail="1">›</button></div></div></div>'
def suite():
    return '<section class="section suite"><div class="wrap">'+hgroup('Product suite','From rider to running order.','Four separately scoped products follow the work from the first signed page to the venue-specific handoff. Venue Fit is the first paid evaluation.')+productcards()+'</div></section>'
def console(): return scenic.console()
def review():
    return '<section class="section reviewchapter"><div class="wrap reviewsplit"><div class="reviewsticky">'+hgroup('Review workflow','Evidence first.<br><em>A person decides.</em>')+'<div class="evidencefold" aria-hidden="true"><span class="mono">VF-031 / REVIEW TRACE</span><strong class="reviewstate">Source comparison</strong><div class="reviewmeter"><i></i></div><p class="tracepassage">NI-R04 · “Astra 40 profile at LX-04.”</p></div></div>'+steps([('Read the two sources','Check the rider passage against the dated inventory or plan. The reference travels with the proposed finding.'),('Check the proposed match','The document model suggests a comparison. The technical lead checks the actual fixture, space and local conditions.'),('Record the outcome','Approve a supported substitution or assign follow-up. Every open item stays visible in the export.')])+'</div></section>'
def roleblock():
    return '<section class="section rolechapter"><div class="wrap split"><div>'+hgroup('Use cases','One advance, several owners.','Each role has a different question to settle before the truck arrives.')+scenic.route()+'</div><div class="rolelist">'+''.join(f'<details {"open" if i==0 else ""}><summary>{r[1]}</summary><h3>{r[2]}</h3><p>{r[3]}</p>{a(r[0],"Explore the workflow","textlink")}</details>' for i,r in enumerate(R))+'</div></div></section>'
def pricemini():
    return '<section class="section pricechapter"><div class="wrap">'+hgroup('Commercial scope','Test it on a season you know.')+'<div class="twocards"><article>'+ey('First commitment')+'<h3>Paid Venue Fit evaluation</h3><p>Agree on the buyer, approved records, named technical lead and comparison threshold. Each pilot has its own quote and signed scope.</p>'+cta('pilot','Scope the evaluation','dark')+'</article><article>'+ey('Annual price hypothesis')+'<h3>$18,000 <small>/ year</small></h3><p>Proposed promoter or venue-group subscription with event tiers. Confirm volume, implementation effort and decision to renew during discovery.</p>'+a('pricing','See pricing assumptions','textlink')+'</article></div></div></section>'
def hero(kicker,title,desc,buttons='',visual='',kind=''):
    return '<section class="subhero '+kind+'"><div class="wrap '+('herosplit' if visual else 'readhead')+'"><div>'+ey(kicker)+'<h1>'+title+'</h1><p class="lead">'+desc+'</p><div class="actions">'+buttons+'</div></div>'+visual+'</div></section>'
def section(t,b,label=''): return '<section class="section"><div class="wrap">'+(hgroup(label,t) if label else '<h2>'+t+'</h2>')+b+'</div></section>'
hero_home='<section class="homehero" aria-label="VenueAlign introduction"><img class="heroimage" src="assets/scenic-hero.webp" width="1800" height="882" fetchpriority="high" alt="A miniature touring stage with terracotta scenic flats, a painted teal sky and a brass work lamp."><div class="hshade"></div><div class="stage-light" aria-hidden="true"></div><div class="stage-wings" aria-hidden="true"><i></i><i></i></div><div class="wrap homeinner"><div class="herohead"><h1><span><i>Advance</i></span> <span><i>the show.</i></span></h1><p>Find the rider requirements a venue still needs to resolve.</p><div class="actions">'+cta('demo','Open Venue Fit <b aria-hidden="true">↗</b>','accent')+'</div></div></div><button type="button" class="replay-scene" hidden>'+icon('replay')+'Replay opening</button></section>'
problem='<section class="section problemchapter"><div class="wrap split"><div>'+hgroup('The advance problem','The rider travels.<br><em>The room changes.</em>','The same signed rider can reach five rooms with five different inventories. When a missing fixture or a stage-width mismatch surfaces at load-in, the team may need a rental or a new schedule.')+a('problem','See where the handoff breaks','textlink')+'</div><figure class="problemphoto"><img loading="lazy" src="assets/model-workshop.webp" alt="A model maker’s bench with the painted set, a lighting fixture and its paper elevation."><figcaption><span>Field study</span><span>Equipment advance</span></figcaption></figure></div></section>'
evidence='<section class="section evidence"><div class="wrap split"><div>'+hgroup('Inside the workbench','Inside the Meridian Hall advance.','At Meridian Hall, a requested fixture is missing and the plan leaves the clear stage width uncertain. Inspect the sources, approve one substitution and see what stays open.')+cta('demo','Open the case workbench','accent')+a('platform','Explore the shared platform','underlight')+'</div>'+console()+'</div></section>'
results='<section class="section feedback"><div class="wrap split"><div>'+hgroup('Reviews & feedback','What does the reviewer need?','The pilot compares the suggested findings with final rentals and the decisions your technical leads actually made.')+a('results','Read the evaluation scorecard','textlink')+'</div><div class="reviewnote">'+ey('Sample reviewer note · fictional')+'<blockquote>“I can sign off the substitute. I still need someone in the room to check the clear width.”</blockquote><p>Inez Park · Technical lead in the Meridian Hall walkthrough</p>'+a('feedback','Leave preview feedback','textlink')+'</div></div></section>'
