page('index','Tour and venue production advance','Find the rider requirements a venue still needs to resolve. Explore a fictional five-stop tour and the proposed Venue Fit pilot.',hero_home+scenic.elevation()+problem+evidence+suite()+review()+roleblock()+results+pricemini()+section('Before the evaluation','<div class="faqgrid">'+faq(FAQs)+scenic.checklist()+'</div>','Common questions')+close())
