for r in R:
    page(r[0],r[1],r[3],hero('Use case · '+r[1],r[2],r[3],cta('demo','Explore the decision','dark'),visual=scenic.supporting_visual(r[0]))+section('Work through a stop',steps([('Start with the local question',r[4]),('Carry the outcome forward',r[5])]))+close())
def form(label,fields,submit,kind,desc):
    return f'<form class="intake" data-form="{kind}"><h2>{label}</h2><p>{desc}</p><div class="fields">'+''.join(fields)+f'</div><p class="formnote">This preview prepares a local download. No request is delivered to VenueAlign.</p><button class="btn dark" type="submit">{submit}</button><div class="formresult" aria-live="polite"></div></form>'
def field(name,label,kind='text',opts=None,req=True):
    must=' required' if req else ''
    if opts: control=f'<select name="{name}"{must}><option value="">Choose an option</option>'+''.join(f'<option value="{esc(x)}">{esc(x)}</option>' for x in opts)+'</select>'
    elif kind=='textarea': control=f'<textarea name="{name}" rows="3"{must}></textarea>'
    else: control=f'<input name="{name}" type="{kind}" autocomplete="'+{'email':'email','organization':'organization','name':'name'}.get(name,'off')+f'"{must}>'
    return f'<label class="field {("full" if kind=="textarea" else "")}"><span>{label}</span>{control}</label>'
ident=[field('email','Work email','email'),field('organization','Organization'),field('role','Your role',opts=['Touring production manager','Venue technical lead','Advance coordinator','Promoter or budget owner','Supplier or rental house','Other'])]
consent=field('follow_up','Follow-up preference',opts=['Yes, I would welcome follow-up','No follow-up, keep this as a draft'])
