formpage('pilot','Paid pilot','Scope a Venue Fit evaluation.','Compare one season of advance files with final rental amendments and technical decisions. Document the current process before the comparison begins.',noteitems(pilotitems),form('Prepare your pilot brief',ident+[field('interest','Pilot interest',opts=['Compare one season of advance files','Scope one participating venue','Explore venue network participation']),field('authority','Budget authority',opts=['I own the budget','I can introduce the signer','Signer still to identify']),field('permission','Data access status',opts=['Data owner has authorized review','Authorization requested','Records or owner still to identify']),field('lead','Technical review coverage',opts=['Lead named for every participating stop','Some leads identified','Reviewer still to identify']),field('baseline','Current advance process','textarea'),consent],'Download pilot brief','pilot','Capture the proposed scope, baseline and permissions for a discovery conversation.'))
