page('privacy','Preview privacy','How demo decisions, downloads and interaction events work in this preview.',hero('Preview notice','Privacy in the preview.','The walkthrough uses invented sources and organizations. Please keep live rider documents and personal information out of the demo.',visual=scenic.supporting_visual('privacy'))+section('What the preview stores',noteitems([('Local decisions','The browser can remember reviewer state for the fictional workbench. Use the workbench reset to restore its sample state.'),('Forms and downloads','Submitted form values generate a local file. The preview has no lead-delivery endpoint. Your email and form entries are excluded from interaction events.'),('Interaction events','The site records event names and timestamps locally for product views, walkthrough starts, reviewer interactions, pilot interest and qualified pilot briefs. Export is local. Clear this preview’s local data below.'),('Hosting','The hosting platform handles requests for site assets. A funded deployment needs its own reviewed retention, access and privacy terms.')])+'<button class="btn outline" id="wipe">Clear local VenueAlign data</button><p id="wipeStatus" role="status"></p>'))
page('terms','Preview terms','The purpose and limits of the research-stage concept.',hero('Preview notice','Using the fictional walkthrough.','VenueAlign illustrates a proposed product workflow. Dates, people, documents, equipment and decisions in the sample are invented.',visual=scenic.supporting_visual('terms'))+section('Scope of the preview',noteitems([('Records','Example exports are demonstration artifacts. Retain the simulated-data label when sharing an example.'),('Operational authority','A named, qualified technical lead reviews actual equipment, power, rigging and physical setup in the venue. A simulated approval has no operational authority.'),('Commercial terms','Public price figures are hypotheses. Pilot scope, data rights, deliverables and price require a separately accepted agreement.'),('Attribution','The brand, interface, diagrams, fictional passages and editorial imagery were created for this concept. Market references are credited on the sources page.')]))+a('sources','Research and sources','textlink'))
page('404','Page unavailable','Recover your place in the VenueAlign preview.',hero('Page unavailable','This stop is off the route.','Return to the product overview or open the current fictional tour.',cta('index','Return home','dark')+cta('demo','Open walkthrough','outline'),visual=scenic.supporting_visual('404')))
page('sources','Research and sources','Market references, visual references and fictional record provenance.',hero('Research & sources','Where the evidence comes from.','The market references document existing practices. The Meridian Hall walkthrough uses independently written, fictional records.',visual=scenic.supporting_visual('sources'))+section('Existing workflow and tools',noteitems([('RiderForge','RiderForge publishes features for rider creation, stage plots, PDF import, AI review, venue checklists and production packs. Local teams can flag unavailable gear. <a class="textlink" href="https://www.riderforge.app/features.html">RiderForge feature inventory</a>'),('Manual substitute','A signed rider, venue advance checklist and technical lead can already settle many equipment questions. The pilot asks which decisions still need follow-up and whether linked evidence improves the comparison.'),('Open question','This preview has no measured advantage over RiderForge or a buyer’s manual workflow. Verify the same cases against actual amendments and reviewed decisions.')]))+section('Original preview materials','<p class="lead">Night Index, Meridian Hall, the sample equipment, document excerpts and buyer account are fictional. The interface, diagrams, editorial images and copy were made for VenueAlign. Each example export carries the simulated-data label.</p>'+a('demo','Inspect the sources in context','textlink')))
capture_block=section('The reviewed record', '<figure class="screenproof"><picture><source media="(max-width:600px)" srcset="assets/captures/venue-fit-390.webp"><img loading="lazy" src="assets/captures/venue-fit-1440.webp" width="1440" alt="Venue Fit after Inez Park approved Luma P4. Dated rider and inventory sources, the unsupported Arc P3 alternative, and the open stage-spacing case remain in the stop record."></picture><figcaption>Meridian Hall · VF-031 reviewed locally. VF-032 awaits a clear-width measurement. DEMO · SIMULATED DATA.</figcaption></figure><div class="actions"><a class="textlink" href="assets/captures/venue-fit-1440.webp">Full desktop capture</a><a class="textlink" href="assets/captures/venue-fit-390.webp">Full mobile capture</a></div>', 'Browser capture')
